CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS tracks(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,artist TEXT NOT NULL DEFAULT '',duration_seconds INTEGER,file_name TEXT NOT NULL,file_size BIGINT,file_fingerprint TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(user_id,file_fingerprint));
CREATE TABLE IF NOT EXISTS playlists(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS playlist_tracks(playlist_id UUID NOT NULL REFERENCES playlists(id) ON DELETE CASCADE,track_id UUID NOT NULL REFERENCES tracks(id) ON DELETE CASCADE,position INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(playlist_id,track_id));
CREATE TABLE IF NOT EXISTS user_settings(user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,watch_folder TEXT NOT NULL DEFAULT '',break_every INTEGER NOT NULL DEFAULT 4,break_minutes INTEGER NOT NULL DEFAULT 3,playback_mode TEXT NOT NULL DEFAULT 'show',updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
